use std::time::Instant;

use http::{Method, Uri};
use uuid::Uuid;

/// Immutable request metadata shared by gateway policy layers.
#[derive(Debug, Clone)]
pub struct RequestContext {
    /// Unique identifier generated by Relay or accepted from a trusted header.
    pub request_id: Uuid,
    /// Request method observed at the edge.
    pub method: Method,
    /// Original request URI.
    pub uri: Uri,
    /// Monotonic time at which processing began.
    pub started_at: Instant,
    /// Matched route, populated after routing.
    pub route: Option<String>,
    /// Selected upstream endpoint, populated before forwarding.
    pub upstream: Option<String>,
    /// Number of retry attempts already made.
    pub retry_count: u32,
}

impl RequestContext {
    /// Creates a context for a newly accepted request.
    pub fn new(method: Method, uri: Uri) -> Self {
        Self {
            request_id: Uuid::new_v4(),
            method,
            uri,
            started_at: Instant::now(),
            route: None,
            upstream: None,
            retry_count: 0,
        }
    }
}
